(15421, 'Proverbs 1:9', 'Proverbs', 1, 9, '&nbsp;د هغوئ نصيحتونه به ستا د سر دپاره ښائسته سهره او ستا د غاړې دپاره د عزت هار وى.', NULL, '&nbsp;د هغوئ نصيحتونه به ستا د سر دپاره ښائسته سهره او ستا د غاړې دپاره د عزت هار وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15422, 'Proverbs 1:10', 'Proverbs', 1, 10, '&nbsp;زما زويه، کله چې ګناهګاران ستا د بې‌لارې کولو کوشش کوى، نو د هغوئ نه ځان ساته.', NULL, '&nbsp;زما زويه، کله چې ګناهګاران ستا د بې‌لارې کولو کوشش کوى، نو د هغوئ نه ځان ساته.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15423, 'Proverbs 1:11', 'Proverbs', 1, 11, '&nbsp;کۀ چرې هغوئ ووائى، ”راځه، چې يو ځائ شُو او د پټ ځائ نه ګزار وکړُو او قتل وکړُو. راځه چې په يو بې‌ګناه کس باندې هسې د خوند دپاره غلې حمله وکړُو.', NULL, '&nbsp;کۀ چرې هغوئ ووائى، ”راځه، چې يو ځائ شُو او د پټ ځائ نه ګزار وکړُو او قتل وکړُو. راځه چې په يو بې‌ګناه کس باندې هسې د خوند دپاره غلې حمله وکړُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15424, 'Proverbs 1:12', 'Proverbs', 1, 12, '&nbsp;راځه چې د قبر په شان هغوئ ژوندى تېر کړُو، د هغوئ په شان لکه څوک چې د مرګ کندې ته کوزيږى.', NULL, '&nbsp;راځه چې د قبر په شان هغوئ ژوندى تېر کړُو، د هغوئ په شان لکه څوک چې د مرګ کندې ته کوزيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15425, 'Proverbs 1:13', 'Proverbs', 1, 13, '&nbsp;مونږ به هر قِسمه قيمتى څيزونه حاصل کړُو او د لوټ د مال نه به خپل کورونه ډک کړُو.', NULL, '&nbsp;مونږ به هر قِسمه قيمتى څيزونه حاصل کړُو او د لوټ د مال نه به خپل کورونه ډک کړُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15426, 'Proverbs 1:14', 'Proverbs', 1, 14, '&nbsp;راځه مونږ سره ملګرے شه او مونږ چې څۀ لوټ کړُو نو په هغې کښې به تا له هم برخه درکړُو.“', NULL, '&nbsp;راځه مونږ سره ملګرے شه او مونږ چې څۀ لوټ کړُو نو په هغې کښې به تا له هم برخه درکړُو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15427, 'Proverbs 1:15', 'Proverbs', 1, 15, '&nbsp;زما زويه، د داسې خلقو سره مۀ ځه، او د هغوئ په نقش قدم مۀ ځه.', NULL, '&nbsp;زما زويه، د داسې خلقو سره مۀ ځه، او د هغوئ په نقش قدم مۀ ځه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15428, 'Proverbs 1:16', 'Proverbs', 1, 16, '&nbsp;ځکه چې هغوئ د بدکارۍ طرف ته په منډه روان وى، او د وينې تويولو په اړخ تېزۍ سره روان وى.', NULL, '&nbsp;ځکه چې هغوئ د بدکارۍ طرف ته په منډه روان وى، او د وينې تويولو په اړخ تېزۍ سره روان وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15429, 'Proverbs 1:17', 'Proverbs', 1, 17, '&nbsp;د يو مارغۀ د سترګو د وړاندې جال خورول څومره بې‌فائدې دى.', NULL, '&nbsp;د يو مارغۀ د سترګو د وړاندې جال خورول څومره بې‌فائدې دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15430, 'Proverbs 1:18', 'Proverbs', 1, 18, '&nbsp;خو دغه شان خلق د خپل ځان دپاره دام خوروى، داسې دام چې هغوئ به په خپله په کښې تباه شى.', NULL, '&nbsp;خو دغه شان خلق د خپل ځان دپاره دام خوروى، داسې دام چې هغوئ به په خپله په کښې تباه شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15431, 'Proverbs 1:19', 'Proverbs', 1, 19, '&nbsp;هم دغه به وى اَنجام د هغه کسانو څوک چې د ناجائزه ‎پېسو ګټلو لالچى وى نو په دې وجه به د خپل ژوند نه لاس ووينځى.', NULL, '&nbsp;هم دغه به وى اَنجام د هغه کسانو څوک چې د ناجائزه ‎پېسو ګټلو لالچى وى نو په دې وجه به د خپل ژوند نه لاس ووينځى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15432, 'Proverbs 1:20', 'Proverbs', 1, 20, '&nbsp;حِکمت په لارو کوڅو کښې په تېزه چغې وهى، او په چوکونو کښې په اوچت آواز نعرې وهى.', NULL, '&nbsp;حِکمت په لارو کوڅو کښې په تېزه چغې وهى، او په چوکونو کښې په اوچت آواز نعرې وهى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15433, 'Proverbs 1:21', 'Proverbs', 1, 21, '&nbsp;د بازار په ګڼه کښې هغه چغې وهى، او د ښار په دروازو کښې چرته چې خلق راغونډيږى هلته تقرير کوى،', NULL, '&nbsp;د بازار په ګڼه کښې هغه چغې وهى، او د ښار په دروازو کښې چرته چې خلق راغونډيږى هلته تقرير کوى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15434, 'Proverbs 1:22', 'Proverbs', 1, 22, '&nbsp;”جاهله خلقو، تاسو به تر کومې پورې ساده ګان يئ؟ ترڅو پورې به تاسو مسخره کوونکى په خپلو مسخرو کښې خوشحاله يئ؟ ترڅو پورې به تاسو بې‌وقوفان عِلم نه نفرت کوئ؟', NULL, '&nbsp;”جاهله خلقو، تاسو به تر کومې پورې ساده ګان يئ؟ ترڅو پورې به تاسو مسخره کوونکى په خپلو مسخرو کښې خوشحاله يئ؟ ترڅو پورې به تاسو بې‌وقوفان عِلم نه نفرت کوئ؟', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15435, 'Proverbs 1:23', 'Proverbs', 1, 23, '&nbsp;راشئ او زما سختې خبرې واورئ. زۀ به خپل زړۀ نه تاسو خبر کړم او تاسو به هوښيار کړم.', NULL, '&nbsp;راشئ او زما سختې خبرې واورئ. زۀ به خپل زړۀ نه تاسو خبر کړم او تاسو به هوښيار کړم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15436, 'Proverbs 1:24', 'Proverbs', 1, 24, '&nbsp;ما تاسو ته څو ځله آوازونه وکړل خو تاسو رانۀ غلئ. زۀ تاسو له درغلم خو تاسو ما ته توجو رانۀ کړه،', NULL, '&nbsp;ما تاسو ته څو ځله آوازونه وکړل خو تاسو رانۀ غلئ. زۀ تاسو له درغلم خو تاسو ما ته توجو رانۀ کړه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15437, 'Proverbs 1:25', 'Proverbs', 1, 25, '&nbsp;تاسو زما ټول نصيحتونه نظر انداز کړل او زما اصلاح کول مو رد کړل،', NULL, '&nbsp;تاسو زما ټول نصيحتونه نظر انداز کړل او زما اصلاح کول مو رد کړل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15438, 'Proverbs 1:26', 'Proverbs', 1, 26, '&nbsp;خو چې کله تاسو په تکليف کښې پرېوځئ نو زۀ به په تاسو پورې ملنډې کوم، او زۀ به تاسو پورې خندا کوم کله چې تاسو بدبختى راګېر کړى،', NULL, '&nbsp;خو چې کله تاسو په تکليف کښې پرېوځئ نو زۀ به په تاسو پورې ملنډې کوم، او زۀ به تاسو پورې خندا کوم کله چې تاسو بدبختى راګېر کړى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15439, 'Proverbs 1:27', 'Proverbs', 1, 27, '&nbsp;کله چې بدبختى لکه د طوفان درباندې راشى، او چې مصيبت لکه د سيلۍ په شان درباندې راشى او چې مصيبت او سختى په تاسو باندې غالبه شى،', NULL, '&nbsp;کله چې بدبختى لکه د طوفان درباندې راشى، او چې مصيبت لکه د سيلۍ په شان درباندې راشى او چې مصيبت او سختى په تاسو باندې غالبه شى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15440, 'Proverbs 1:28', 'Proverbs', 1, 28, '&nbsp;نو بيا چې کله دوئ ما ته چغې وهى، خو زۀ به دوئ له جواب نۀ ورکوم. دوئ به ما هر چرته د زړۀ نه ولټوى، خو دوئ به ما پېدا نۀ کړى.', NULL, '&nbsp;نو بيا چې کله دوئ ما ته چغې وهى، خو زۀ به دوئ له جواب نۀ ورکوم. دوئ به ما هر چرته د زړۀ نه ولټوى، خو دوئ به ما پېدا نۀ کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15441, 'Proverbs 1:29', 'Proverbs', 1, 29, '&nbsp;ځکه چې دوئ د پوهې نه نفرت کولو او دوئ د مالِک خُدائ نه نۀ يرېدل خوښ کړل،', NULL, '&nbsp;ځکه چې دوئ د پوهې نه نفرت کولو او دوئ د مالِک خُدائ نه نۀ يرېدل خوښ کړل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15442, 'Proverbs 1:30', 'Proverbs', 1, 30, '&nbsp;دوئ زما نصيحت رد کړو، کله چې مې اصلاح کوله نو دوئ ما ته هيڅ توجو رانۀ کړه.', NULL, '&nbsp;دوئ زما نصيحت رد کړو، کله چې مې اصلاح کوله نو دوئ ما ته هيڅ توجو رانۀ کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15443, 'Proverbs 1:31', 'Proverbs', 1, 31, '&nbsp;نو په دې وجه دوئ به د خپل چال چلن ترخه مېوه وخورى او په خپلو منصوبو به ماړۀ شى.', NULL, '&nbsp;نو په دې وجه دوئ به د خپل چال چلن ترخه مېوه وخورى او په خپلو منصوبو به ماړۀ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15444, 'Proverbs 1:32', 'Proverbs', 1, 32, '&nbsp;د ساده خلقو سرکشى به دوئ مړۀ کړى، کم عقلان د خپل قناعت په وجه تباه کيږى.', NULL, '&nbsp;د ساده خلقو سرکشى به دوئ مړۀ کړى، کم عقلان د خپل قناعت په وجه تباه کيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15445, 'Proverbs 1:33', 'Proverbs', 1, 33, '&nbsp;خو هر څوک چې ما ته غوږ نيسى نو هغه به په امن کښې اوسيږى، او د نقصان څۀ يره به پرې نۀ وى.“', NULL, '&nbsp;خو هر څوک چې ما ته غوږ نيسى نو هغه به په امن کښې اوسيږى، او د نقصان څۀ يره به پرې نۀ وى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15446, 'Proverbs 2:1', 'Proverbs', 2, 1, '&nbsp;زما زويه، کۀ تۀ زما خبرې ومنې او زما حُکمونه په زړۀ کښې محفوظ کړې،', NULL, '&nbsp;زما زويه، کۀ تۀ زما خبرې ومنې او زما حُکمونه په زړۀ کښې محفوظ کړې،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15447, 'Proverbs 2:2', 'Proverbs', 2, 2, '&nbsp;او د عقل خبرو ته غوږ ونيسې او خپل زړۀ د هوښيارتيا طرف ته مائل کړې،', NULL, '&nbsp;او د عقل خبرو ته غوږ ونيسې او خپل زړۀ د هوښيارتيا طرف ته مائل کړې،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
