(15457, 'Proverbs 2:12', 'Proverbs', 2, 12, '&nbsp;عقل به تا د بدکاره خلقو نه ساتى، او د هغوئ نه چې د چا خبرې چې غلطې دى،', NULL, '&nbsp;عقل به تا د بدکاره خلقو نه ساتى، او د هغوئ نه چې د چا خبرې چې غلطې دى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
