(15460, 'Proverbs 2:15', 'Proverbs', 2, 15, '&nbsp;او دغه کسان په کږو وږو سر دى او د هغوئ چال چلن د ټګۍ دے.', NULL, '&nbsp;او دغه کسان په کږو وږو سر دى او د هغوئ چال چلن د ټګۍ دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15461, 'Proverbs 2:16', 'Proverbs', 2, 16, '&nbsp;نو هغه به تا د بدکارې ښځې نه وساتى، د هغې زناکارې نه څوک چې په خوږو خبرو تا دوکه کول غواړى،', NULL, '&nbsp;نو هغه به تا د بدکارې ښځې نه وساتى، د هغې زناکارې نه څوک چې په خوږو خبرو تا دوکه کول غواړى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15462, 'Proverbs 2:17', 'Proverbs', 2, 17, '&nbsp;چا چې خپل د ځوانۍ د وخت خاوند پرېښے دے او خپل لوظ يې هېر کړو کوم يې چې د خُدائ پاک په وړاندې کړے وو.', NULL, '&nbsp;چا چې خپل د ځوانۍ د وخت خاوند پرېښے دے او خپل لوظ يې هېر کړو کوم يې چې د خُدائ پاک په وړاندې کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15463, 'Proverbs 2:18', 'Proverbs', 2, 18, '&nbsp;د هغې کور ته تلل مرګ ته دعوت دے، او د هغې د کور لار د قبر لار ده.', NULL, '&nbsp;د هغې کور ته تلل مرګ ته دعوت دے، او د هغې د کور لار د قبر لار ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15464, 'Proverbs 2:19', 'Proverbs', 2, 19, '&nbsp;څوک چې هغې له ورشى نو هغه بيا نۀ راواپس کيږى او هغه بيا هيڅکله د ژوند په لاره راتلے نۀ شى.', NULL, '&nbsp;څوک چې هغې له ورشى نو هغه بيا نۀ راواپس کيږى او هغه بيا هيڅکله د ژوند په لاره راتلے نۀ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15465, 'Proverbs 2:20', 'Proverbs', 2, 20, '&nbsp;نو بيا تۀ د ښو خلقو په طريقو تلل کوه او د صادقانو په لارو کښې پاتې شه.', NULL, '&nbsp;نو بيا تۀ د ښو خلقو په طريقو تلل کوه او د صادقانو په لارو کښې پاتې شه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15466, 'Proverbs 2:21', 'Proverbs', 2, 21, '&nbsp;نو نېکان به په مُلک کښې اوسيږى، او بې‌داغه خلق به په کښې پاتې شى.', NULL, '&nbsp;نو نېکان به په مُلک کښې اوسيږى، او بې‌داغه خلق به په کښې پاتې شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15467, 'Proverbs 2:22', 'Proverbs', 2, 22, '&nbsp;خو بدعمله به د هغه مُلک نه وشړلے شى، او غداران به ترې د بېخ نه وويستلے شى.', NULL, '&nbsp;خو بدعمله به د هغه مُلک نه وشړلے شى، او غداران به ترې د بېخ نه وويستلے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15468, 'Proverbs 3:1', 'Proverbs', 3, 1, '&nbsp;زما زويه، زما لارښودنه مۀ هېروه، خو زما حُکمونه په خپل زړۀ کښې وساته.', NULL, '&nbsp;زما زويه، زما لارښودنه مۀ هېروه، خو زما حُکمونه په خپل زړۀ کښې وساته.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15469, 'Proverbs 3:2', 'Proverbs', 3, 2, '&nbsp;زما تعليم به ستا عمر سېوا کړى او خوشحالى به درکړى.', NULL, '&nbsp;زما تعليم به ستا عمر سېوا کړى او خوشحالى به درکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15470, 'Proverbs 3:3', 'Proverbs', 3, 3, '&nbsp;هيڅکله مينه او وفادارى د خپل ځان نه مۀ لرې کوه. دوئ د خپلې غاړې هار کړه او د خپل زړۀ په تخته باندې يې وليکه.', NULL, '&nbsp;هيڅکله مينه او وفادارى د خپل ځان نه مۀ لرې کوه. دوئ د خپلې غاړې هار کړه او د خپل زړۀ په تخته باندې يې وليکه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15471, 'Proverbs 3:4', 'Proverbs', 3, 4, '&nbsp;نو بيا به تۀ د انسانانو او د خُدائ پاک په نظر کښې محبوبيت او نېک نامى حاصله کړې.', NULL, '&nbsp;نو بيا به تۀ د انسانانو او د خُدائ پاک په نظر کښې محبوبيت او نېک نامى حاصله کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15472, 'Proverbs 3:5', 'Proverbs', 3, 5, '&nbsp;په خپل ټول زړۀ سره په مالِک خُدائ باندې توکل کوه. او په خپله پوهه باندې تکيه مۀ کوه.', NULL, '&nbsp;په خپل ټول زړۀ سره په مالِک خُدائ باندې توکل کوه. او په خپله پوهه باندې تکيه مۀ کوه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15473, 'Proverbs 3:6', 'Proverbs', 3, 6, '&nbsp;چې تۀ هر کار کوې نو په هغې کښې مالِک خُدائ ياد ساته، او هغه به تا ته صحيح لاره ښائى.', NULL, '&nbsp;چې تۀ هر کار کوې نو په هغې کښې مالِک خُدائ ياد ساته، او هغه به تا ته صحيح لاره ښائى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15474, 'Proverbs 3:7', 'Proverbs', 3, 7, '&nbsp;په خپل عقل باندې مۀ مغروره کېږه، د مالِک خُدائ نه يرېږه او بدعملى پرېږده.', NULL, '&nbsp;په خپل عقل باندې مۀ مغروره کېږه، د مالِک خُدائ نه يرېږه او بدعملى پرېږده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15475, 'Proverbs 3:8', 'Proverbs', 3, 8, '&nbsp;نو په دې به ستا بدن رغيږى او ستا هډُوکى به پرې تازه شى.', NULL, '&nbsp;نو په دې به ستا بدن رغيږى او ستا هډُوکى به پرې تازه شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15476, 'Proverbs 3:9', 'Proverbs', 3, 9, '&nbsp;په خپل مال دولت سره د مالِک خُدائ عزت کوه، او د خپل ټول فصل په وړومبۍ مېوې سره.', NULL, '&nbsp;په خپل مال دولت سره د مالِک خُدائ عزت کوه، او د خپل ټول فصل په وړومبۍ مېوې سره.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15477, 'Proverbs 3:10', 'Proverbs', 3, 10, '&nbsp;نو بيا به ستا ګودامونه ډک شى او د سر نه به اوړى، او ستا د چاټۍ د خولې نه به نوى مے اوړى.', NULL, '&nbsp;نو بيا به ستا ګودامونه ډک شى او د سر نه به اوړى، او ستا د چاټۍ د خولې نه به نوى مے اوړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15478, 'Proverbs 3:11', 'Proverbs', 3, 11, '&nbsp;زما زويه، د مالِک خُدائ اصلاح مۀ رد کوه او کله چې هغه تا تنبيه کوى په هغې باندې مۀ خفه کېږه.', NULL, '&nbsp;زما زويه، د مالِک خُدائ اصلاح مۀ رد کوه او کله چې هغه تا تنبيه کوى په هغې باندې مۀ خفه کېږه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15479, 'Proverbs 3:12', 'Proverbs', 3, 12, '&nbsp;ځکه چې مالِک خُدائ چې چا سره مينه کوى نو هم هغه تنبيه کوى لکه څنګه چې يو پلار هم هغه زوئ تنبيه کوى کوم چې هغۀ ته ګران وى.', NULL, '&nbsp;ځکه چې مالِک خُدائ چې چا سره مينه کوى نو هم هغه تنبيه کوى لکه څنګه چې يو پلار هم هغه زوئ تنبيه کوى کوم چې هغۀ ته ګران وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15480, 'Proverbs 3:13', 'Proverbs', 3, 13, '&nbsp;بختور ‎دے هغه څوک چې حِکمت حاصل کړى، او هغه څوک چې پوهه حاصله کړى.', NULL, '&nbsp;بختور ‎دے هغه څوک چې حِکمت حاصل کړى، او هغه څوک چې پوهه حاصله کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15481, 'Proverbs 3:14', 'Proverbs', 3, 14, '&nbsp;ځکه چې دا د سپينو زرو نه ډېر قيمتى دے او د دې ګټه د سرو زرو نه هم ډېره ښۀ ده.', NULL, '&nbsp;ځکه چې دا د سپينو زرو نه ډېر قيمتى دے او د دې ګټه د سرو زرو نه هم ډېره ښۀ ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15482, 'Proverbs 3:15', 'Proverbs', 3, 15, '&nbsp;دا د قيمتى کاڼو نه هم ګران دے او ستا د خوښې يو څيز هم د دې برابر نۀ دے.', NULL, '&nbsp;دا د قيمتى کاڼو نه هم ګران دے او ستا د خوښې يو څيز هم د دې برابر نۀ دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15483, 'Proverbs 3:16', 'Proverbs', 3, 16, '&nbsp;د عقل په ښى لاس کښې اوږد ژوندون دے، او د هغۀ په ګس لاس کښې عزت او دولت دے.', NULL, '&nbsp;د عقل په ښى لاس کښې اوږد ژوندون دے، او د هغۀ په ګس لاس کښې عزت او دولت دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15484, 'Proverbs 3:17', 'Proverbs', 3, 17, '&nbsp;د هغۀ لارې برکتى دى، او د هغۀ ټولې لارې پُراَمنه دى.', NULL, '&nbsp;د هغۀ لارې برکتى دى، او د هغۀ ټولې لارې پُراَمنه دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
