(15490, 'Proverbs 3:23', 'Proverbs', 3, 23, '&nbsp;نو بيا به تۀ په حِفاظت سره په خپله لار روان يې او ستا پښه به تيندک ونۀ خورى.', NULL, '&nbsp;نو بيا به تۀ په حِفاظت سره په خپله لار روان يې او ستا پښه به تيندک ونۀ خورى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15491, 'Proverbs 3:24', 'Proverbs', 3, 24, '&nbsp;کله چې تۀ څملې، تۀ به نۀ يرېږې، او تۀ به په خوږ خوب اودۀ کېږې.', NULL, '&nbsp;کله چې تۀ څملې، تۀ به نۀ يرېږې، او تۀ به په خوږ خوب اودۀ کېږې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15492, 'Proverbs 3:25', 'Proverbs', 3, 25, '&nbsp;نو د ناګهانى افت نه به نۀ يرېږې او نۀ به د هغه تباهۍ نه يرېږې کومه چې په بدعملو باندې راځى.', NULL, '&nbsp;نو د ناګهانى افت نه به نۀ يرېږې او نۀ به د هغه تباهۍ نه يرېږې کومه چې په بدعملو باندې راځى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15493, 'Proverbs 3:26', 'Proverbs', 3, 26, '&nbsp;نو مالِک خُدائ به ستا ډاډ وى، او هغه به ستا پښې په دام کښې د ګېرولو نه وساتى.', NULL, '&nbsp;نو مالِک خُدائ به ستا ډاډ وى، او هغه به ستا پښې په دام کښې د ګېرولو نه وساتى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15494, 'Proverbs 3:27', 'Proverbs', 3, 27, '&nbsp;څوک چې حاجتمند وى د هغوئ سره ښېګړه مۀ پرېږده، کۀ چرې دا کار ستا وس کښې وى،', NULL, '&nbsp;څوک چې حاجتمند وى د هغوئ سره ښېګړه مۀ پرېږده، کۀ چرې دا کار ستا وس کښې وى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15495, 'Proverbs 3:28', 'Proverbs', 3, 28, '&nbsp;کۀ چرې تۀ اوس د خپل ګاونډى سره مدد کولے شې، نو ورته مۀ وايه چې، ”سبا راشه چې مدد دې وکړم.“', NULL, '&nbsp;کۀ چرې تۀ اوس د خپل ګاونډى سره مدد کولے شې، نو ورته مۀ وايه چې، ”سبا راشه چې مدد دې وکړم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15496, 'Proverbs 3:29', 'Proverbs', 3, 29, '&nbsp;د خپل ګاونډى خلاف هغۀ ته د نقصان ورکولو منصوبه مۀ جوړوه، څوک چې ستا په خوا کښې اوسيږى او په تا باور کوى.', NULL, '&nbsp;د خپل ګاونډى خلاف هغۀ ته د نقصان ورکولو منصوبه مۀ جوړوه، څوک چې ستا په خوا کښې اوسيږى او په تا باور کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15497, 'Proverbs 3:30', 'Proverbs', 3, 30, '&nbsp;په يو کس باندې هيڅ بې‌هيڅه اِلزام مۀ لګوه ترڅو چې هغۀ تا ته نقصان نۀ وى درسولے.', NULL, '&nbsp;په يو کس باندې هيڅ بې‌هيڅه اِلزام مۀ لګوه ترڅو چې هغۀ تا ته نقصان نۀ وى درسولے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15498, 'Proverbs 3:31', 'Proverbs', 3, 31, '&nbsp;د ظالم سره سيالى مۀ کوه او مۀ د هغۀ په نقش قدم عمل کوه،', NULL, '&nbsp;د ظالم سره سيالى مۀ کوه او مۀ د هغۀ په نقش قدم عمل کوه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15499, 'Proverbs 3:32', 'Proverbs', 3, 32, '&nbsp;ځکه چې مالِک خُدائ د هغوئ نه نفرت کوى څوک چې بدکاره وى، خو هغه د نېکانو سره دوستانه تعلق ساتى.', NULL, '&nbsp;ځکه چې مالِک خُدائ د هغوئ نه نفرت کوى څوک چې بدکاره وى، خو هغه د نېکانو سره دوستانه تعلق ساتى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15500, 'Proverbs 3:33', 'Proverbs', 3, 33, '&nbsp;د بدعمله په کور مالِک خُدائ لعنت ورَوى، خو هغه د صادق په کور باندې برکت ورَوى.', NULL, '&nbsp;د بدعمله په کور مالِک خُدائ لعنت ورَوى، خو هغه د صادق په کور باندې برکت ورَوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15501, 'Proverbs 3:34', 'Proverbs', 3, 34, '&nbsp;هغه د مغروره مسخره کوونکو پورې مسخرې کوى، خو په عاجز خويه باندې خپل فضل کوى.', NULL, '&nbsp;هغه د مغروره مسخره کوونکو پورې مسخرې کوى، خو په عاجز خويه باندې خپل فضل کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
