(15503, 'Proverbs 4:1', 'Proverbs', 4, 1, '&nbsp;زما زامنو د خپل پلار هدايت ته غوږ ونيسئ. او هغې ته توجو ورکړئ او پوهه حاصله کړئ.', NULL, '&nbsp;زما زامنو د خپل پلار هدايت ته غوږ ونيسئ. او هغې ته توجو ورکړئ او پوهه حاصله کړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15504, 'Proverbs 4:2', 'Proverbs', 4, 2, '&nbsp;ځکه چې زۀ تاسو ته ښۀ تعليم درښايم، نو زما تعليمات مۀ هېروئ.', NULL, '&nbsp;ځکه چې زۀ تاسو ته ښۀ تعليم درښايم، نو زما تعليمات مۀ هېروئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15505, 'Proverbs 4:3', 'Proverbs', 4, 3, '&nbsp;هر کله چې زۀ د خپل پلار په کور کښې هلک وم، او د خپلې مور اېک يو نيازبين زوئ وم،', NULL, '&nbsp;هر کله چې زۀ د خپل پلار په کور کښې هلک وم، او د خپلې مور اېک يو نيازبين زوئ وم،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15506, 'Proverbs 4:4', 'Proverbs', 4, 4, '&nbsp;هغۀ ما ته تعليم راکړو او وې وئيل، ”په خپل ټول زړۀ سره زما نصيحت راټينګ کړه، زما په حُکمونو عمل کوه نو ستا ژوند به په خير تير شى.', NULL, '&nbsp;هغۀ ما ته تعليم راکړو او وې وئيل، ”په خپل ټول زړۀ سره زما نصيحت راټينګ کړه، زما په حُکمونو عمل کوه نو ستا ژوند به په خير تير شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15507, 'Proverbs 4:5', 'Proverbs', 4, 5, '&nbsp;حِکمت حاصل کړه، او پوهه حاصله کړه، زما خبرې مۀ هېروه او مۀ د هغې نه مخ اړوه.', NULL, '&nbsp;حِکمت حاصل کړه، او پوهه حاصله کړه، زما خبرې مۀ هېروه او مۀ د هغې نه مخ اړوه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15508, 'Proverbs 4:6', 'Proverbs', 4, 6, '&nbsp;عقل ته مۀ شاه کوه، ځکه چې هغه به ستا حفاظت وکړى، د هغۀ سره مينه کوه نو هغه به په تا باندې نظر ساتى.', NULL, '&nbsp;عقل ته مۀ شاه کوه، ځکه چې هغه به ستا حفاظت وکړى، د هغۀ سره مينه کوه نو هغه به په تا باندې نظر ساتى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15509, 'Proverbs 4:7', 'Proverbs', 4, 7, '&nbsp;حِکمت حاصلول د ټولو نه اهم کار دے، د نورو څيزونو د حاصلولو سره سره پوهه هم حاصله کړه.', NULL, '&nbsp;حِکمت حاصلول د ټولو نه اهم کار دے، د نورو څيزونو د حاصلولو سره سره پوهه هم حاصله کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15510, 'Proverbs 4:8', 'Proverbs', 4, 8, '&nbsp;د حِکمت عزت کوه او دا به تا لوئ کړى. دې ته غاړه ورکړه نو دا به تا عزتمند کړى.', NULL, '&nbsp;د حِکمت عزت کوه او دا به تا لوئ کړى. دې ته غاړه ورکړه نو دا به تا عزتمند کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15511, 'Proverbs 4:9', 'Proverbs', 4, 9, '&nbsp;دا به ستا سر د فضل سهرې سره ښائسته کړى او د شان او شوکت تاج به در په سر کړى.“', NULL, '&nbsp;دا به ستا سر د فضل سهرې سره ښائسته کړى او د شان او شوکت تاج به در په سر کړى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15512, 'Proverbs 4:10', 'Proverbs', 4, 10, '&nbsp;زما زويه، ما ته غوږ شه. زۀ چې درته څۀ وايم هغه کوه، نو په دې کولو سره به ستا عمر اوږد شى.', NULL, '&nbsp;زما زويه، ما ته غوږ شه. زۀ چې درته څۀ وايم هغه کوه، نو په دې کولو سره به ستا عمر اوږد شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15513, 'Proverbs 4:11', 'Proverbs', 4, 11, '&nbsp;ما درته د عقل او حِکمت لارښودنه وکړه او په نېغه لار مې روان کړې.', NULL, '&nbsp;ما درته د عقل او حِکمت لارښودنه وکړه او په نېغه لار مې روان کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
