(15515, 'Proverbs 4:13', 'Proverbs', 4, 13, '&nbsp;زما نصيحتونه راټينګ کړه او دا مۀ پرېږده چې ستا نه لاړ شى. د هغوئ ښۀ حفاظت وکړه ځکه چې دا ستا ژوندون دے.', NULL, '&nbsp;زما نصيحتونه راټينګ کړه او دا مۀ پرېږده چې ستا نه لاړ شى. د هغوئ ښۀ حفاظت وکړه ځکه چې دا ستا ژوندون دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
