(15518, 'Proverbs 4:16', 'Proverbs', 4, 16, '&nbsp;ترڅو پورې چې دوئ غلط کار نۀ وى کړے تر هغې خوب نۀ ورځى، ترڅو پورې چې دوئ چا ته تيندک نۀ وى ورکړے نو دوئ تر هغې پورې آرام نۀ کوى.', NULL, '&nbsp;ترڅو پورې چې دوئ غلط کار نۀ وى کړے تر هغې خوب نۀ ورځى، ترڅو پورې چې دوئ چا ته تيندک نۀ وى ورکړے نو دوئ تر هغې پورې آرام نۀ کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
