(15530, 'Proverbs 5:1', 'Proverbs', 5, 1, '&nbsp;زما زويه، زما پوهې ته توجو ورکړه، او زما د حِکمت خبرو ته ښۀ غوږ ونيسه.', NULL, '&nbsp;زما زويه، زما پوهې ته توجو ورکړه، او زما د حِکمت خبرو ته ښۀ غوږ ونيسه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15531, 'Proverbs 5:2', 'Proverbs', 5, 2, '&nbsp;نو بيا به تۀ تميز حاصل کړې، او ستا شونډې به عِلم او حِکمت محفوظوى.', NULL, '&nbsp;نو بيا به تۀ تميز حاصل کړې، او ستا شونډې به عِلم او حِکمت محفوظوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15532, 'Proverbs 5:3', 'Proverbs', 5, 3, '&nbsp;ځکه چې د زناکارې ښځې د شونډو نه شات راڅاڅى. او د هغې خبرې د تېلو نه زياتې نرمې دى،', NULL, '&nbsp;ځکه چې د زناکارې ښځې د شونډو نه شات راڅاڅى. او د هغې خبرې د تېلو نه زياتې نرمې دى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15533, 'Proverbs 5:4', 'Proverbs', 5, 4, '&nbsp;خو په آخر کښې هغه د ګنډير په شان ترخه، او د دوه مخيزې تُورې په شان تيره ده.', NULL, '&nbsp;خو په آخر کښې هغه د ګنډير په شان ترخه، او د دوه مخيزې تُورې په شان تيره ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15534, 'Proverbs 5:5', 'Proverbs', 5, 5, '&nbsp;د هغې پښې د مرګ په طرف روانې دى، او د هغې قدمونه سيدها د قبر طرف ته لارښودنه کوى.', NULL, '&nbsp;د هغې پښې د مرګ په طرف روانې دى، او د هغې قدمونه سيدها د قبر طرف ته لارښودنه کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15535, 'Proverbs 5:6', 'Proverbs', 5, 6, '&nbsp;هغه د ژوند د لارې په حقله سوچ نۀ کوى، د هغې لارې کږې وږې دى، خو هغه پرې نۀ پوهيږى.', NULL, '&nbsp;هغه د ژوند د لارې په حقله سوچ نۀ کوى، د هغې لارې کږې وږې دى، خو هغه پرې نۀ پوهيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15536, 'Proverbs 5:7', 'Proverbs', 5, 7, '&nbsp;نو بيا اوس زما زويه، ما ته غوږ ونيسه. او زۀ چې درته څۀ وايم نو د هغې نه مۀ اوړه.', NULL, '&nbsp;نو بيا اوس زما زويه، ما ته غوږ ونيسه. او زۀ چې درته څۀ وايم نو د هغې نه مۀ اوړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15537, 'Proverbs 5:8', 'Proverbs', 5, 8, '&nbsp;د داسې ښځې نه ځان لرې ساته. او چې د هغې د کور دروازې ته هم ورنزدې نۀ شى', NULL, '&nbsp;د داسې ښځې نه ځان لرې ساته. او چې د هغې د کور دروازې ته هم ورنزدې نۀ شى', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15538, 'Proverbs 5:9', 'Proverbs', 5, 9, '&nbsp;هسې نه چې خپل عزت نورو ته ورکړې او بې‌عزته شې. او د خپل ژوند واګې د ظالمانو رحم و کرم ته وسپارې،', NULL, '&nbsp;هسې نه چې خپل عزت نورو ته ورکړې او بې‌عزته شې. او د خپل ژوند واګې د ظالمانو رحم و کرم ته وسپارې،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15539, 'Proverbs 5:10', 'Proverbs', 5, 10, '&nbsp;هسې نه چې پردى ستا په مال مزې وکړى، او ستا د ژوند محنت د بل چا کور مالا مال کړى.', NULL, '&nbsp;هسې نه چې پردى ستا په مال مزې وکړى، او ستا د ژوند محنت د بل چا کور مالا مال کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15540, 'Proverbs 5:11', 'Proverbs', 5, 11, '&nbsp;او د خپل عمر په آخر کښې به تۀ زبيرګى او فريادونه کوې، هرکله چې ستا غوښې او بدن خوړين شى،', NULL, '&nbsp;او د خپل عمر په آخر کښې به تۀ زبيرګى او فريادونه کوې، هرکله چې ستا غوښې او بدن خوړين شى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15541, 'Proverbs 5:12', 'Proverbs', 5, 12, '&nbsp;نو تۀ به ووائې، ”ما د اصلاح نه څومره نفرت کولو. او څومره به زما زړۀ اصلاح کول رټل،', NULL, '&nbsp;نو تۀ به ووائې، ”ما د اصلاح نه څومره نفرت کولو. او څومره به زما زړۀ اصلاح کول رټل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15542, 'Proverbs 5:13', 'Proverbs', 5, 13, '&nbsp;ما به د خپلو اُستاذانو تابعدارى نۀ کوله، او نۀ به مې خپلو لارښودونکو ته غوږ نيولو.', NULL, '&nbsp;ما به د خپلو اُستاذانو تابعدارى نۀ کوله، او نۀ به مې خپلو لارښودونکو ته غوږ نيولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15543, 'Proverbs 5:14', 'Proverbs', 5, 14, '&nbsp;نو زۀ د تباهۍ په غاړه ولاړ يم، او په ډېرو خلقو کښې وشرمېدم.“', NULL, '&nbsp;نو زۀ د تباهۍ په غاړه ولاړ يم، او په ډېرو خلقو کښې وشرمېدم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15544, 'Proverbs 5:15', 'Proverbs', 5, 15, '&nbsp;د خپلې ذخيرې اوبۀ څښه، او صرف د خپلې ښځې سره کوروالے کوه لکه څنګه چې د خپل کوهى نه روانې اوبۀ څښې.', NULL, '&nbsp;د خپلې ذخيرې اوبۀ څښه، او صرف د خپلې ښځې سره کوروالے کوه لکه څنګه چې د خپل کوهى نه روانې اوبۀ څښې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
