(15546, 'Proverbs 5:17', 'Proverbs', 5, 17, '&nbsp;نو دا دې يواځې ستا وى، کله دې هم د پردو سره شريک نۀ شى.', NULL, '&nbsp;نو دا دې يواځې ستا وى، کله دې هم د پردو سره شريک نۀ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15547, 'Proverbs 5:18', 'Proverbs', 5, 18, '&nbsp;ستا چينې دې برکتى شى، د خپلې ښځې سره خوشحاله اوسه چې ستا په ځوانۍ کښې ورسره وادۀ شوے وو،', NULL, '&nbsp;ستا چينې دې برکتى شى، د خپلې ښځې سره خوشحاله اوسه چې ستا په ځوانۍ کښې ورسره وادۀ شوے وو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
