(15556, 'Proverbs 6:4', 'Proverbs', 6, 4, '&nbsp;زر ورشه مۀ اودۀ کېږه او خپلې سترګې مرغۍ مرغۍ کېدو ته مۀ پرېږده.', NULL, '&nbsp;زر ورشه مۀ اودۀ کېږه او خپلې سترګې مرغۍ مرغۍ کېدو ته مۀ پرېږده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
