(15572, 'Proverbs 6:20', 'Proverbs', 6, 20, '&nbsp;زما زويه، د پلار په حُکمونو عمل کوه، او د خپلې مور لارښودنه مۀ هېروه.', NULL, '&nbsp;زما زويه، د پلار په حُکمونو عمل کوه، او د خپلې مور لارښودنه مۀ هېروه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
