(15574, 'Proverbs 6:22', 'Proverbs', 6, 22, '&nbsp;هرکله چې تۀ روان يې نو هغه به ستا رهنمائى کوى، او کله چې اودۀ يې نو هغه به ستا حفاظت کوى، هرکله چې راويښ شې، نو هغه به درته مشوره درکوى.', NULL, '&nbsp;هرکله چې تۀ روان يې نو هغه به ستا رهنمائى کوى، او کله چې اودۀ يې نو هغه به ستا حفاظت کوى، هرکله چې راويښ شې، نو هغه به درته مشوره درکوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15575, 'Proverbs 6:23', 'Proverbs', 6, 23, '&nbsp;نو د هغوئ حُکمونه ډيوه ده او د هغوئ هدايت رڼا ده، او د هغوئ اصلاح د ژوندون لار ده.', NULL, '&nbsp;نو د هغوئ حُکمونه ډيوه ده او د هغوئ هدايت رڼا ده، او د هغوئ اصلاح د ژوندون لار ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
