(15579, 'Proverbs 6:27', 'Proverbs', 6, 27, '&nbsp;څوک په خپله جولۍ کښې بل شوے اور د کپړو سوزېدلو نه بغېر اوچتولے شى څۀ؟', NULL, '&nbsp;څوک په خپله جولۍ کښې بل شوے اور د کپړو سوزېدلو نه بغېر اوچتولے شى څۀ؟', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15580, 'Proverbs 6:28', 'Proverbs', 6, 28, '&nbsp;څوک په ګرمو سکروټو باندې بغېر د پښو پولۍ کېدو او سوزېدو نه ګرځېدلے شى څۀ؟', NULL, '&nbsp;څوک په ګرمو سکروټو باندې بغېر د پښو پولۍ کېدو او سوزېدو نه ګرځېدلے شى څۀ؟', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
