(15598, 'Proverbs 7:11', 'Proverbs', 7, 11, '&nbsp;هغه بې‌شرمه او بې‌حيا ښځه وه چې ټوله ورځ هواګيره ګرځېدله.', NULL, '&nbsp;هغه بې‌شرمه او بې‌حيا ښځه وه چې ټوله ورځ هواګيره ګرځېدله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15599, 'Proverbs 7:12', 'Proverbs', 7, 12, '&nbsp;هغه تل په کوڅو، او په چوکونو کښې ګرځى، او د ښار په هر ګوټ کښې ولاړه وى.', NULL, '&nbsp;هغه تل په کوڅو، او په چوکونو کښې ګرځى، او د ښار په هر ګوټ کښې ولاړه وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15600, 'Proverbs 7:13', 'Proverbs', 7, 13, '&nbsp;هغې هغۀ له غاړه ورکړه او ښُکل يې کړو، او په خپلو بې‌شرمو سترګو سره يې هغۀ ته ووئيل،', NULL, '&nbsp;هغې هغۀ له غاړه ورکړه او ښُکل يې کړو، او په خپلو بې‌شرمو سترګو سره يې هغۀ ته ووئيل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15601, 'Proverbs 7:14', 'Proverbs', 7, 14, '&nbsp;”نن ما کره د قربانۍ غوښه ده او ما خپل نذر پوره کړو.', NULL, '&nbsp;”نن ما کره د قربانۍ غوښه ده او ما خپل نذر پوره کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15602, 'Proverbs 7:15', 'Proverbs', 7, 15, '&nbsp;نو زۀ بهر راووتلم چې تا سره مِلاو شم، ما ستا لټون کولو او تۀ راته مِلاو شوې.', NULL, '&nbsp;نو زۀ بهر راووتلم چې تا سره مِلاو شم، ما ستا لټون کولو او تۀ راته مِلاو شوې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15603, 'Proverbs 7:16', 'Proverbs', 7, 16, '&nbsp;ما په خپل کټ باندې د مِصر رنګارنګ د لټې څادرونه اچولى دى.', NULL, '&nbsp;ما په خپل کټ باندې د مِصر رنګارنګ د لټې څادرونه اچولى دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15604, 'Proverbs 7:17', 'Proverbs', 7, 17, '&nbsp;ما په خپل کټ باندې د مُر چيړ، عُود او دارچينۍ خوشبو لګولې ده.', NULL, '&nbsp;ما په خپل کټ باندې د مُر چيړ، عُود او دارچينۍ خوشبو لګولې ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15605, 'Proverbs 7:18', 'Proverbs', 7, 18, '&nbsp;راځه چې تر سحره پورې په مينه کښې ډُوب شُو. او د يو بل د مينې نه خوند واخلو.', NULL, '&nbsp;راځه چې تر سحره پورې په مينه کښې ډُوب شُو. او د يو بل د مينې نه خوند واخلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15606, 'Proverbs 7:19', 'Proverbs', 7, 19, '&nbsp;ځکه چې زما خاوند په کور کښې نشته. هغه په لرې سفر باندې تلے دے.', NULL, '&nbsp;ځکه چې زما خاوند په کور کښې نشته. هغه په لرې سفر باندې تلے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15607, 'Proverbs 7:20', 'Proverbs', 7, 20, '&nbsp;هغۀ خپل جيب د پېسو نه ډک کړے دے، او د دې مياشتې تر آخره به واپس نۀ راځى.“', NULL, '&nbsp;هغۀ خپل جيب د پېسو نه ډک کړے دے، او د دې مياشتې تر آخره به واپس نۀ راځى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15608, 'Proverbs 7:21', 'Proverbs', 7, 21, '&nbsp;نو په نرمو خبرو سره يې هغه غلط کړو، او د هغې پستو خبرو وغلولو.', NULL, '&nbsp;نو په نرمو خبرو سره يې هغه غلط کړو، او د هغې پستو خبرو وغلولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15609, 'Proverbs 7:22', 'Proverbs', 7, 22, '&nbsp;نو هغه سمدستى هغې پسې د يو داسې غوَيى په شان روان شو لکه چې حلالېدو له روان وى، لکه چې هوسۍ په دام کښې ونښلى', NULL, '&nbsp;نو هغه سمدستى هغې پسې د يو داسې غوَيى په شان روان شو لکه چې حلالېدو له روان وى، لکه چې هوسۍ په دام کښې ونښلى', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15610, 'Proverbs 7:23', 'Proverbs', 7, 23, '&nbsp;ترڅو چې يو غشے د هغۀ زړۀ غوڅ کړى. هغه د يو داسې مارغۀ په شان وو چې د دام طرف ته منډې وهى، هغۀ ته پته نۀ وى چې هغه به د ژوند نه لاس ووينځى.', NULL, '&nbsp;ترڅو چې يو غشے د هغۀ زړۀ غوڅ کړى. هغه د يو داسې مارغۀ په شان وو چې د دام طرف ته منډې وهى، هغۀ ته پته نۀ وى چې هغه به د ژوند نه لاس ووينځى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15611, 'Proverbs 7:24', 'Proverbs', 7, 24, '&nbsp;نو بيا زما زامنو، ما ته غوږ ونيسئ، زۀ چې درته څۀ وايم نو هغې ته توجو وکړئ.', NULL, '&nbsp;نو بيا زما زامنو، ما ته غوږ ونيسئ، زۀ چې درته څۀ وايم نو هغې ته توجو وکړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15612, 'Proverbs 7:25', 'Proverbs', 7, 25, '&nbsp;خپل زړۀ ته اجازت مۀ ورکوه چې د داسې ښځې طرف ته مائل شى، او يا د هغې په غلطو لارو روان شى.', NULL, '&nbsp;خپل زړۀ ته اجازت مۀ ورکوه چې د داسې ښځې طرف ته مائل شى، او يا د هغې په غلطو لارو روان شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15613, 'Proverbs 7:26', 'Proverbs', 7, 26, '&nbsp;هغه د ډېرو کسانو د تباهۍ سبب شوې ده او د بې‌شمېره کسانو د مرګ سبب شوې ده.', NULL, '&nbsp;هغه د ډېرو کسانو د تباهۍ سبب شوې ده او د بې‌شمېره کسانو د مرګ سبب شوې ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15614, 'Proverbs 7:27', 'Proverbs', 7, 27, '&nbsp;د هغې کور د قبر طرف ته لار ده، او دا د مرګ دالان ته لارښودنه کول دى.', NULL, '&nbsp;د هغې کور د قبر طرف ته لار ده، او دا د مرګ دالان ته لارښودنه کول دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15615, 'Proverbs 8:1', 'Proverbs', 8, 1, '&nbsp;غوږ شئ. ولې پوهه آوازونه نۀ کوى څۀ؟ پوهې خپل آواز نۀ دے پورته کړے څۀ؟', NULL, '&nbsp;غوږ شئ. ولې پوهه آوازونه نۀ کوى څۀ؟ پوهې خپل آواز نۀ دے پورته کړے څۀ؟', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15616, 'Proverbs 8:2', 'Proverbs', 8, 2, '&nbsp;هغه په اوچتو ځايونو د لارې په خوا کښې، او چرته چې لارې په خپلو کښې ملاويږى ولاړه وى.', NULL, '&nbsp;هغه په اوچتو ځايونو د لارې په خوا کښې، او چرته چې لارې په خپلو کښې ملاويږى ولاړه وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
