(15618, 'Proverbs 8:4', 'Proverbs', 8, 4, '&nbsp;”اے خلقو زۀ تاسو ټولو ته آواز کوم، او په زمکه باندې ټولو انسانانو ته آواز کوم.', NULL, '&nbsp;”اے خلقو زۀ تاسو ټولو ته آواز کوم، او په زمکه باندې ټولو انسانانو ته آواز کوم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15619, 'Proverbs 8:5', 'Proverbs', 8, 5, '&nbsp;اے ساده خلقو، احتياط زده کړئ، اے بې‌وقوفو. عقل حاصل کړئ.', NULL, '&nbsp;اے ساده خلقو، احتياط زده کړئ، اے بې‌وقوفو. عقل حاصل کړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15620, 'Proverbs 8:6', 'Proverbs', 8, 6, '&nbsp;غوږ شئ. ما سره ستاسو دپاره اعلىٰ خبرې دى، او زۀ چې شونډې پرانيزم نو هغه څۀ وايم څۀ چې صحيح وى.', NULL, '&nbsp;غوږ شئ. ما سره ستاسو دپاره اعلىٰ خبرې دى، او زۀ چې شونډې پرانيزم نو هغه څۀ وايم څۀ چې صحيح وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15621, 'Proverbs 8:7', 'Proverbs', 8, 7, '&nbsp;زما خولۀ هغه څۀ وائى څۀ چې رښتيا وى، ځکه چې زما شونډې د دروغو نه نفرت کوى.', NULL, '&nbsp;زما خولۀ هغه څۀ وائى څۀ چې رښتيا وى، ځکه چې زما شونډې د دروغو نه نفرت کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15622, 'Proverbs 8:8', 'Proverbs', 8, 8, '&nbsp;زما د خولې ټولې خبرې صحيح دى، يو خبره يې هم کږه يا د دوکې نۀ ده.', NULL, '&nbsp;زما د خولې ټولې خبرې صحيح دى، يو خبره يې هم کږه يا د دوکې نۀ ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
