(15636, 'Proverbs 8:22', 'Proverbs', 8, 22, '&nbsp;مالِک خُدائ د هر څۀ نه وړاندې چې نور څۀ پېدا کړى، د ټولو نه اول يې زۀ پېدا کړم.', NULL, '&nbsp;مالِک خُدائ د هر څۀ نه وړاندې چې نور څۀ پېدا کړى، د ټولو نه اول يې زۀ پېدا کړم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
