(15638, 'Proverbs 8:24', 'Proverbs', 8, 24, '&nbsp;کله چې لا سمندر نۀ وو زۀ پېدا شوے وم، کله چې لا د چينو اوبۀ نۀ وې روانې شوې.', NULL, '&nbsp;کله چې لا سمندر نۀ وو زۀ پېدا شوے وم، کله چې لا د چينو اوبۀ نۀ وې روانې شوې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15639, 'Proverbs 8:25', 'Proverbs', 8, 25, '&nbsp;مخکښې د دې نه چې لا غرونه او غونډۍ په خپل ځائ نۀ وُو ولاړ زۀ پېدا شوے وم،', NULL, '&nbsp;مخکښې د دې نه چې لا غرونه او غونډۍ په خپل ځائ نۀ وُو ولاړ زۀ پېدا شوے وم،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15640, 'Proverbs 8:26', 'Proverbs', 8, 26, '&nbsp;د هغې نه وړاندې چې لا خُدائ پاک زمکه او د هغې پټى او لا نۀ يې د دُنيا خاوره پېدا کړې وه چې زۀ پېدا وم.', NULL, '&nbsp;د هغې نه وړاندې چې لا خُدائ پاک زمکه او د هغې پټى او لا نۀ يې د دُنيا خاوره پېدا کړې وه چې زۀ پېدا وم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15641, 'Proverbs 8:27', 'Proverbs', 8, 27, '&nbsp;زۀ هلته وم هر کله چې هغۀ آسمان په خپل ځائ ودرولو، او کله چې يې د سمندر په مخ د فضا لهرونه خوارۀ کړل،', NULL, '&nbsp;زۀ هلته وم هر کله چې هغۀ آسمان په خپل ځائ ودرولو، او کله چې يې د سمندر په مخ د فضا لهرونه خوارۀ کړل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15642, 'Proverbs 8:28', 'Proverbs', 8, 28, '&nbsp;کله چې هغۀ بره وريځ مقرر کړه او کله چې د سمندر د ډکولو دپاره چينې جوړې کړې،', NULL, '&nbsp;کله چې هغۀ بره وريځ مقرر کړه او کله چې د سمندر د ډکولو دپاره چينې جوړې کړې،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15643, 'Proverbs 8:29', 'Proverbs', 8, 29, '&nbsp;او کله چې هغۀ سمندر ته حد مقرر کړو، ترڅو چې اوبۀ د هغۀ د حُکم نه يو قدم هم زيات وانۀ خلى، او کله چې هغۀ د زمکې بنيادونه کېښودل نو زۀ هلته وم.', NULL, '&nbsp;او کله چې هغۀ سمندر ته حد مقرر کړو، ترڅو چې اوبۀ د هغۀ د حُکم نه يو قدم هم زيات وانۀ خلى، او کله چې هغۀ د زمکې بنيادونه کېښودل نو زۀ هلته وم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
