(15708, 'Proverbs 11:8', 'Proverbs', 11, 8, '&nbsp;صادق سړے د تکليفونو نه خلاص وى، او دا تکليفونه د هغوئ په ځائ په بدعمله خلقو باندې راځى.', NULL, '&nbsp;صادق سړے د تکليفونو نه خلاص وى، او دا تکليفونه د هغوئ په ځائ په بدعمله خلقو باندې راځى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
