(15710, 'Proverbs 11:10', 'Proverbs', 11, 10, '&nbsp;کله چې صادقان برکتى شى نو ټول ښار په هغوئ خوشحالى کوى، او کله چې بدعمله هلاک شى نو د خوشحالۍ چغې راوچتې شى.', NULL, '&nbsp;کله چې صادقان برکتى شى نو ټول ښار په هغوئ خوشحالى کوى، او کله چې بدعمله هلاک شى نو د خوشحالۍ چغې راوچتې شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
