(15788, 'Proverbs 14:4', 'Proverbs', 14, 4, '&nbsp;چرته چې غوَيى نۀ وى هلته اخور خالى وى، خو د غوَيى د طاقت په وجه ډېر فصل پېدا کيږى.', NULL, '&nbsp;چرته چې غوَيى نۀ وى هلته اخور خالى وى، خو د غوَيى د طاقت په وجه ډېر فصل پېدا کيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
