(15817, 'Proverbs 14:33', 'Proverbs', 14, 33, '&nbsp;د هوښيارانو په زړۀ کښې حِکمت ځائ نيسى، خو تر دې چې حِکمت په کم عقلو کښې هم خپل ځان ښکاره کوى.', NULL, '&nbsp;د هوښيارانو په زړۀ کښې حِکمت ځائ نيسى، خو تر دې چې حِکمت په کم عقلو کښې هم خپل ځان ښکاره کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
