(15819, 'Proverbs 14:35', 'Proverbs', 14, 35, '&nbsp;بادشاه په هوښيار نوکر خوشحاليږى، خو هغه څوک چې شرمېدلى کارونه کوى د هغۀ قهر راوچتوى.', NULL, '&nbsp;بادشاه په هوښيار نوکر خوشحاليږى، خو هغه څوک چې شرمېدلى کارونه کوى د هغۀ قهر راوچتوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
