(15822, 'Proverbs 15:3', 'Proverbs', 15, 3, '&nbsp;د مالِک خُدائ سترګې هر چرته موجودې دى، هغه ښۀ او بد دواړو باندې نظر ساتى.', NULL, '&nbsp;د مالِک خُدائ سترګې هر چرته موجودې دى، هغه ښۀ او بد دواړو باندې نظر ساتى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
