(15826, 'Proverbs 15:7', 'Proverbs', 15, 7, '&nbsp;د هوښيارانو شونډې عِلم خوروى، خو د بې‌عقله په زړۀ کښې داسې څۀ نۀ وى.', NULL, '&nbsp;د هوښيارانو شونډې عِلم خوروى، خو د بې‌عقله په زړۀ کښې داسې څۀ نۀ وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15827, 'Proverbs 15:8', 'Proverbs', 15, 8, '&nbsp;مالِک خُدائ د بدکارانو د قربانۍ نه نفرت کوى، خو د نېکانو دُعا هغه خوشحالوى.', NULL, '&nbsp;مالِک خُدائ د بدکارانو د قربانۍ نه نفرت کوى، خو د نېکانو دُعا هغه خوشحالوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
