(15829, 'Proverbs 15:10', 'Proverbs', 15, 10, '&nbsp;د هغه چا به سخت تربيت وشى څوک چې صحيح لاره پرېږدى، څوک چې د اِصلاح کولو نه نفرت کوى نو هغه به مړ شى.', NULL, '&nbsp;د هغه چا به سخت تربيت وشى څوک چې صحيح لاره پرېږدى، څوک چې د اِصلاح کولو نه نفرت کوى نو هغه به مړ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15830, 'Proverbs 15:11', 'Proverbs', 15, 11, '&nbsp;دا چې عالمِ ارواح او دوزخ دواړه مالِک خُدائ ته ښکارى، نو د انسان زړۀ به ورته څومره زيات څرګند وى؟', NULL, '&nbsp;دا چې عالمِ ارواح او دوزخ دواړه مالِک خُدائ ته ښکارى، نو د انسان زړۀ به ورته څومره زيات څرګند وى؟', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15831, 'Proverbs 15:12', 'Proverbs', 15, 12, '&nbsp;مسخره کوونکى اصلاح نۀ خوښوى، نو ځکه چې د هوښيارانو سره مشوره نۀ کوى.', NULL, '&nbsp;مسخره کوونکى اصلاح نۀ خوښوى، نو ځکه چې د هوښيارانو سره مشوره نۀ کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
