(15836, 'Proverbs 15:17', 'Proverbs', 15, 17, '&nbsp;دال ساګ دې وى خو چې مينې سره وى، کۀ چرګ وى او نفرت ورسره وى نو فائده يې څۀ ده.', NULL, '&nbsp;دال ساګ دې وى خو چې مينې سره وى، کۀ چرګ وى او نفرت ورسره وى نو فائده يې څۀ ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
