(15856, 'Proverbs 16:4', 'Proverbs', 16, 4, '&nbsp;مالِک خُدائ هر څۀ د خپل مقصد د پوره کولو دپاره پېدا کړى دى، تر دې چې بدکاران يې هم د تباهۍ د ورځې دپاره پېدا کړى دى.', NULL, '&nbsp;مالِک خُدائ هر څۀ د خپل مقصد د پوره کولو دپاره پېدا کړى دى، تر دې چې بدکاران يې هم د تباهۍ د ورځې دپاره پېدا کړى دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
