(15893, 'Proverbs 17:8', 'Proverbs', 17, 8, '&nbsp;رشوت د ورکوونکى دپاره د جادو په شان وى، ځکه هغه چې هر څۀ کوى نو کاميابيږى.', NULL, '&nbsp;رشوت د ورکوونکى دپاره د جادو په شان وى، ځکه هغه چې هر څۀ کوى نو کاميابيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15894, 'Proverbs 17:9', 'Proverbs', 17, 9, '&nbsp;هر هغه څوک چې د نورو خطاګانې معاف کوى نو مينې ته وده ورکوى، خو هر هغه څوک چې يوه خبره بار بار تکراروى نو نزدې دوستان سره جدا کوى.', NULL, '&nbsp;هر هغه څوک چې د نورو خطاګانې معاف کوى نو مينې ته وده ورکوى، خو هر هغه څوک چې يوه خبره بار بار تکراروى نو نزدې دوستان سره جدا کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15895, 'Proverbs 17:10', 'Proverbs', 17, 10, '&nbsp;يو هوښيار کس په يو ځل تنبيه کولو سره دومره زيات متاثره کيږى، نه چې يو کم عقل په سلو کوړو.', NULL, '&nbsp;يو هوښيار کس په يو ځل تنبيه کولو سره دومره زيات متاثره کيږى، نه چې يو کم عقل په سلو کوړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15896, 'Proverbs 17:11', 'Proverbs', 17, 11, '&nbsp;بدکاره صرف سرکشۍ پسې ليونى وى، خو دوئ ته به سخته سزا مِلاو شى.', NULL, '&nbsp;بدکاره صرف سرکشۍ پسې ليونى وى، خو دوئ ته به سخته سزا مِلاو شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15897, 'Proverbs 17:12', 'Proverbs', 17, 12, '&nbsp;دا بهتره ده چې د هغې مېلوګى سره دې واسطه راشى چې بچى ترې چا پټ کړى وى په ځائ د دې چې يو بې‌وقوفه په خپل کم عقلتوب ټينګار کوى.', NULL, '&nbsp;دا بهتره ده چې د هغې مېلوګى سره دې واسطه راشى چې بچى ترې چا پټ کړى وى په ځائ د دې چې يو بې‌وقوفه په خپل کم عقلتوب ټينګار کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15898, 'Proverbs 17:13', 'Proverbs', 17, 13, '&nbsp;کۀ چرته يو انسان د ښو په بدل کښې بد کوى، نو د هغۀ د کور نه به هيڅکله بدى ختمه نۀ شى.', NULL, '&nbsp;کۀ چرته يو انسان د ښو په بدل کښې بد کوى، نو د هغۀ د کور نه به هيڅکله بدى ختمه نۀ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15899, 'Proverbs 17:14', 'Proverbs', 17, 14, '&nbsp;د خراب بحث شروع داسې وى لکه چې د اوبو په بند کښې وړومبے سورے وشى، د دې نه مخکښې چې جنګ شروع نۀ شى نو دا زر ختم کړه.', NULL, '&nbsp;د خراب بحث شروع داسې وى لکه چې د اوبو په بند کښې وړومبے سورے وشى، د دې نه مخکښې چې جنګ شروع نۀ شى نو دا زر ختم کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15900, 'Proverbs 17:15', 'Proverbs', 17, 15, '&nbsp;بدعمله کس پرېښودل، او بې‌ګناه له سزا ورکول، مالِک خُدائ د دې دواړو کارونو نه نفرت کوى.', NULL, '&nbsp;بدعمله کس پرېښودل، او بې‌ګناه له سزا ورکول، مالِک خُدائ د دې دواړو کارونو نه نفرت کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15901, 'Proverbs 17:16', 'Proverbs', 17, 16, '&nbsp;په کم عقل د خرچې کولو څۀ فائده نشته، ځکه چې هغه په خپله د عقل زده کولو خواهش نۀ کوى.', NULL, '&nbsp;په کم عقل د خرچې کولو څۀ فائده نشته، ځکه چې هغه په خپله د عقل زده کولو خواهش نۀ کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15902, 'Proverbs 17:17', 'Proverbs', 17, 17, '&nbsp;دوست په هر وخت کښې مينه کوى، او ورور هغه دے چې په مصيبت کښې په کار راشى.', NULL, '&nbsp;دوست په هر وخت کښې مينه کوى، او ورور هغه دے چې په مصيبت کښې په کار راشى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15903, 'Proverbs 17:18', 'Proverbs', 17, 18, '&nbsp;څوک چې کم عقل وى خپل لاس د ګاونډى په ځائ په ضمانت کښې بل له ورکوى.', NULL, '&nbsp;څوک چې کم عقل وى خپل لاس د ګاونډى په ځائ په ضمانت کښې بل له ورکوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
