(15926, 'Proverbs 18:13', 'Proverbs', 18, 13, '&nbsp;څوک چې د خبرې اورېدو نه مخکښې جواب ورکوى، دا د هغۀ کم عقلتوب دے او د هغۀ شرم دے.', NULL, '&nbsp;څوک چې د خبرې اورېدو نه مخکښې جواب ورکوى، دا د هغۀ کم عقلتوب دے او د هغۀ شرم دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
