(15930, 'Proverbs 18:17', 'Proverbs', 18, 17, '&nbsp;څوک چې په عدالت کښې خپله دعوىٰ اول پېش کړى نو هغه صحيح ښکارى ترڅو چې بل څوک راشى او هغۀ نه تپوسونه شروع کړى.', NULL, '&nbsp;څوک چې په عدالت کښې خپله دعوىٰ اول پېش کړى نو هغه صحيح ښکارى ترڅو چې بل څوک راشى او هغۀ نه تپوسونه شروع کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15931, 'Proverbs 18:18', 'Proverbs', 18, 18, '&nbsp;په پچې اچولو جنګونه ختميږى، او د مضبوطو مخالفينو په مينځ کښې جنګ ختموى.', NULL, '&nbsp;په پچې اچولو جنګونه ختميږى، او د مضبوطو مخالفينو په مينځ کښې جنګ ختموى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15932, 'Proverbs 18:19', 'Proverbs', 18, 19, '&nbsp;د يو خفه شوى ورور رضا کول د يو مضبوط ښار د فتح کولو نه سخت وى، او لانجې د قلعې دروازو ته اړمونه اچوى.', NULL, '&nbsp;د يو خفه شوى ورور رضا کول د يو مضبوط ښار د فتح کولو نه سخت وى، او لانجې د قلعې دروازو ته اړمونه اچوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15933, 'Proverbs 18:20', 'Proverbs', 18, 20, '&nbsp;د خپلې خولې په مېوه انسان خپله خېټه مړه کړى او د خپلو شونډو په فصل هغه مطمئن شى.', NULL, '&nbsp;د خپلې خولې په مېوه انسان خپله خېټه مړه کړى او د خپلو شونډو په فصل هغه مطمئن شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(15934, 'Proverbs 18:21', 'Proverbs', 18, 21, '&nbsp;په ژبه کښې د مرګ او ژوند طاقت شته دے، او څوک چې دې سره مينه کوى هغوئ ته به يې نتيجه مِلاو شى.', NULL, '&nbsp;په ژبه کښې د مرګ او ژوند طاقت شته دے، او څوک چې دې سره مينه کوى هغوئ ته به يې نتيجه مِلاو شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
