(15962, 'Proverbs 19:25', 'Proverbs', 19, 25, '&nbsp;کۀ څوک پېغور کوونکے ووهى نو د دې نه به ساده ګان سبق زده کړى، کۀ چرې پوهه سړے ورټلے شى نو هغه به د دې نه نور عِلم زده کړى.', NULL, '&nbsp;کۀ څوک پېغور کوونکے ووهى نو د دې نه به ساده ګان سبق زده کړى، کۀ چرې پوهه سړے ورټلے شى نو هغه به د دې نه نور عِلم زده کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
