(16002, 'Proverbs 21:6', 'Proverbs', 21, 6, '&nbsp;کوم مال دولت چې په دروغژنه ژبه وګټلے شى نو دا د ختمېدونکى دوند او وژونکى دام په شان دے.', NULL, '&nbsp;کوم مال دولت چې په دروغژنه ژبه وګټلے شى نو دا د ختمېدونکى دوند او وژونکى دام په شان دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
