(16006, 'Proverbs 21:10', 'Proverbs', 21, 10, '&nbsp;بدکاره انسان د بدۍ خواهشمند وى، د هغۀ ګاونډيان هم هيڅ قِسمه رحم د هغۀ نه نۀ وينى.', NULL, '&nbsp;بدکاره انسان د بدۍ خواهشمند وى، د هغۀ ګاونډيان هم هيڅ قِسمه رحم د هغۀ نه نۀ وينى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16007, 'Proverbs 21:11', 'Proverbs', 21, 11, '&nbsp;کله چې يو مسخره کوونکى ته سزا ورکړے شى، نو ساده هم ترې نه عقل زده کړى، خو کله چې د هوښيار لارښودنه وشى، نو هغه ترې نه نور عِلم حاصلوى.', NULL, '&nbsp;کله چې يو مسخره کوونکى ته سزا ورکړے شى، نو ساده هم ترې نه عقل زده کړى، خو کله چې د هوښيار لارښودنه وشى، نو هغه ترې نه نور عِلم حاصلوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16008, 'Proverbs 21:12', 'Proverbs', 21, 12, '&nbsp;صادقه خُدائ هغه هر څۀ وينى کوم چې د بدکاره په کور کښې کيږى، او په بدکاره به هغه تباهى راولى.', NULL, '&nbsp;صادقه خُدائ هغه هر څۀ وينى کوم چې د بدکاره په کور کښې کيږى، او په بدکاره به هغه تباهى راولى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16009, 'Proverbs 21:13', 'Proverbs', 21, 13, '&nbsp;کۀ يو سړے د غريب ژړا فرياد ته خپل غوږونه بند کړى، نو د هغۀ خپله ژړا فرياد به څوک نۀ اورى.', NULL, '&nbsp;کۀ يو سړے د غريب ژړا فرياد ته خپل غوږونه بند کړى، نو د هغۀ خپله ژړا فرياد به څوک نۀ اورى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16010, 'Proverbs 21:14', 'Proverbs', 21, 14, '&nbsp;په پرده کښې تحفه ورکول غصه نرموى، په پټه رشوت ورکول انسان د غټ قهر نه ساتى.', NULL, '&nbsp;په پرده کښې تحفه ورکول غصه نرموى، په پټه رشوت ورکول انسان د غټ قهر نه ساتى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16011, 'Proverbs 21:15', 'Proverbs', 21, 15, '&nbsp;هرکله چې اِنصاف وشى، نو په دې صادق خوشحاليږى، خو بدکاره ترې نه يريږى.', NULL, '&nbsp;هرکله چې اِنصاف وشى، نو په دې صادق خوشحاليږى، خو بدکاره ترې نه يريږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16012, 'Proverbs 21:16', 'Proverbs', 21, 16, '&nbsp;څوک چې د حِکمت د لارې نه بې‌لارې شى، نو هغه به د مړو په ډله کښې شمار شى.', NULL, '&nbsp;څوک چې د حِکمت د لارې نه بې‌لارې شى، نو هغه به د مړو په ډله کښې شمار شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16013, 'Proverbs 21:17', 'Proverbs', 21, 17, '&nbsp;څوک چې د عياشۍ سره مينه کوى نو هغه به غريب شى، څوک چې د ميو او غوړو زېړو سره مينه کوى هغه به مالداره نۀ شى.', NULL, '&nbsp;څوک چې د عياشۍ سره مينه کوى نو هغه به غريب شى، څوک چې د ميو او غوړو زېړو سره مينه کوى هغه به مالداره نۀ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16014, 'Proverbs 21:18', 'Proverbs', 21, 18, '&nbsp;د صادقانو په ځائ بدکاران سزاوار شو، او د هغوئ په ځائ د نافرمانو فديه ورکړے شوه.', NULL, '&nbsp;د صادقانو په ځائ بدکاران سزاوار شو، او د هغوئ په ځائ د نافرمانو فديه ورکړے شوه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
