(16016, 'Proverbs 21:20', 'Proverbs', 21, 20, '&nbsp;د هوښيارانو په کور کښې ښۀ خوراکونه ډېر تير وى، خو کم عقل چې څۀ ګټى هغه څټى.', NULL, '&nbsp;د هوښيارانو په کور کښې ښۀ خوراکونه ډېر تير وى، خو کم عقل چې څۀ ګټى هغه څټى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
