(16078, 'Proverbs 23:22', 'Proverbs', 23, 22, '&nbsp;خپل پلار ته غوږ نيسه، چا چې تا له ژوند درکړے دے، او د خپلې مور بې‌عزتى مۀ کوه کله چې هغه بوډۍ شى.', NULL, '&nbsp;خپل پلار ته غوږ نيسه، چا چې تا له ژوند درکړے دے، او د خپلې مور بې‌عزتى مۀ کوه کله چې هغه بوډۍ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16079, 'Proverbs 23:23', 'Proverbs', 23, 23, '&nbsp;حقيقت حاصل کړه او دا مۀ خرڅوه، او حِکمت، تربيت او پوهه حاصله کړه.', NULL, '&nbsp;حقيقت حاصل کړه او دا مۀ خرڅوه، او حِکمت، تربيت او پوهه حاصله کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16080, 'Proverbs 23:24', 'Proverbs', 23, 24, '&nbsp;د صادق سړى پلار ډېر خوشحاله وى، هغه څوک چې هوښيار زوئ لرى په هغۀ باندې فخر کوى.', NULL, '&nbsp;د صادق سړى پلار ډېر خوشحاله وى، هغه څوک چې هوښيار زوئ لرى په هغۀ باندې فخر کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16081, 'Proverbs 23:25', 'Proverbs', 23, 25, '&nbsp;ستا مور او پلار دې خوشحالى وکړى، او هغه دې خوشحالى وکړى چا چې تۀ زيږولے يې.', NULL, '&nbsp;ستا مور او پلار دې خوشحالى وکړى، او هغه دې خوشحالى وکړى چا چې تۀ زيږولے يې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
