(16086, 'Proverbs 23:30', 'Proverbs', 23, 30, '&nbsp;دا هغوئ دى څوک چې په مےخانو کښې وخت تېروى، او د رنګارنګ ميو پيالۍ څښى.', NULL, '&nbsp;دا هغوئ دى څوک چې په مےخانو کښې وخت تېروى، او د رنګارنګ ميو پيالۍ څښى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
(16087, 'Proverbs 23:31', 'Proverbs', 23, 31, '&nbsp;ميو ته مۀ ګوره کله چې دا سرۀ وى او کله چې په پياله کښې شُغلې وهى او په آسانه سره تېريږى.', NULL, '&nbsp;ميو ته مۀ ګوره کله چې دا سرۀ وى او کله چې په پياله کښې شُغلې وهى او په آسانه سره تېريږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761757891, 1761757891),
